import{_ as r,o as n,c as t,ah as i}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse('{"title":"Teil 2: Das Erbe der Arisierung","description":"","frontmatter":{},"headers":[],"relativePath":"drehbuch/teil-2-das-erbe-der-arisierung.md","filePath":"drehbuch/teil-2-das-erbe-der-arisierung.md"}'),s={name:"drehbuch/teil-2-das-erbe-der-arisierung.md"};function a(d,e,h,l,u,g){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="teil-2-das-erbe-der-arisierung" tabindex="-1">Teil 2: Das Erbe der Arisierung <a class="header-anchor" href="#teil-2-das-erbe-der-arisierung" aria-label="Permalink to &quot;Teil 2: Das Erbe der Arisierung&quot;">​</a></h1><p><strong>Arbeitstitel:</strong> <em>Die Stunde des Schnäppchenjägers</em></p><p><strong>Besetzung:</strong> August Diehl (Der junge Helmut Horten), Oliver Masucci (Dr. Alfred Alsberg &amp; Martha Alsberg - Doppelrolle/Maskenspiel), Birgit Minichmayr (Die Stimme der Geschichte/Heidi Horten in Rückblenden).</p><hr><h2 id="szene-1-duisburg-1933-–-das-stille-beben" tabindex="-1">Szene 1: Duisburg 1933 – Das stille Beben <a class="header-anchor" href="#szene-1-duisburg-1933-–-das-stille-beben" aria-label="Permalink to &quot;Szene 1: Duisburg 1933 – Das stille Beben&quot;">​</a></h2><p><strong>Ort:</strong> Vor dem Haupteingang des Alsberg-Kaufhauses. <strong>Zeit:</strong> Ein grauer Dienstagmorgen.</p><p>Der junge Helmut (August Diehl) steht auf der gegenüberliegenden Straßenseite. Er trägt einen makellosen Mantel. Er beobachtet die Kunden, die zögerlich das jüdische Kaufhaus betreten. Ein SA-Mann steht mit einem Schild „Kauft nicht bei Juden!“ vor der Tür.</p><p><strong>HELMUT</strong> (zu sich selbst, fast klinisch) Das Gebäude ist solide. Die Lage ist erstklassig. Nur der Name... der Name ist im Weg. Er passt nicht mehr in die Zeit.</p><p>Er notiert etwas in sein Notizbuch. Seine Hand zittert nicht. Er ist kein Ideologe, er ist ein Optimierer.</p><hr><h2 id="szene-2-der-junge-helmut-und-das-„dankeschon-neu" tabindex="-1">Szene 2: Der junge Helmut und das „Dankeschön“ (NEU) <a class="header-anchor" href="#szene-2-der-junge-helmut-und-das-„dankeschon-neu" aria-label="Permalink to &quot;Szene 2: Der junge Helmut und das „Dankeschön“ (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Ein verrauchtes Hinterzimmer eines Cafés. <strong>Zeit:</strong> Später am Abend.</p><p>Helmut trifft sich mit einem Gauleiter-Stellvertreter. Der Raum riecht nach billigem Tabak und Machtrausch.</p><p><strong>GAULEITER</strong> Horten, Sie sind jung. Sie sind ehrgeizig. Wir brauchen jemanden, der die... „Marktbereinigung“ übernimmt. Jemand, der keine sentimentalen Bindungen hat.</p><p><strong>HELMUT</strong> (mit kühlem Lächeln) Ich habe nur Bindungen an die Bilanz, Herr Gauleiter. Was die Elsbergs... Alsbergs... angeht: Ich biete ihnen einen fairen Preis. Einen sehr fairen Preis... für die Umstände.</p><p><strong>GAULEITER</strong> Die Umstände, Horten. Genau. Die Umstände machen den Preis. Nicht der Wert.</p><hr><h2 id="szene-3-der-choreografierte-tanz-durch-leere-regale-neu" tabindex="-1">Szene 3: Der choreografierte Tanz durch leere Regale (NEU) <a class="header-anchor" href="#szene-3-der-choreografierte-tanz-durch-leere-regale-neu" aria-label="Permalink to &quot;Szene 3: Der choreografierte Tanz durch leere Regale (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Im Inneren des Kaufhauses Alsberg. <strong>Zeit:</strong> Nach Geschäftsschluss.</p><p>Helmut geht durch die Gänge. Die Kamera folgt ihm in einer langen, fließenden Bewegung. August Diehl spielt Helmut als jemanden, der die Räume bereits „besetzt“, bevor er sie besitzt. Er berührt die Stoffe, testet die Kassen.</p><p><strong>HELMUT</strong> (flüsternd zu den leeren Kleiderständern) Bald seid ihr frei. Frei von den Schatten der Vergangenheit. Ich werde euch neu einkleiden. In Uniformen? Nein. In Träume. Deutsche Träume.</p><p>Er beginnt einen einsamen Walzer in der Kurzwarenabteilung. Es ist eine bizarre, fast unheimliche Szene. Ein Mann, der mit einem Gebäude tanzt, das er gerade stiehlt.</p><hr><h2 id="szene-4-das-protokoll-der-„ubernahme" tabindex="-1">Szene 4: Das Protokoll der „Übernahme“ <a class="header-anchor" href="#szene-4-das-protokoll-der-„ubernahme" aria-label="Permalink to &quot;Szene 4: Das Protokoll der „Übernahme“&quot;">​</a></h2><p><strong>Ort:</strong> Ein stickiges Büro im Duisburger Rathaus. <strong>Zeit:</strong> 23. April 1936.</p><p>Helmut sitzt den Inhabern Hermann Strauß, Ernst und Curt Lauter (Oliver Masucci in Mehrfachrollen) gegenüber. Auf dem Tisch liegt der Kaufvertrag. Die Luft ist schwer von Bürokratie und der nackten Angst der Verkäufer.</p><p><strong>ALFRED / STRAUSS</strong> (mit zittriger Stimme) Herr Horten, 672.963 Reichsmark? Das deckt gerade einmal unser Warenlager. Was ist mit dem Firmenwert? Was ist mit dem Namen Alsberg, den mein Vater über Jahrzehnte aufgebaut hat?</p><p><strong>HELMUT</strong> (kalt, sachlich) Der Name Alsberg ist heute ein Hindernis, meine Herren. Ich biete Ihnen die Befreiung von diesem Hindernis. Ab dem 1. Mai wird dieses Haus unter meinem Namen firmieren. Das ist die kaufmännische Realität des Jahres 1936.</p><p><strong>CURT LAUTER</strong> Es ist eine Zwangsversteigerung unter dem Deckmantel der Legalität, Herr Horten.</p><p><strong>HELMUT</strong> (lehnt sich vor, blättert im Vertrag) Es ist eine Unterschrift, die Ihnen den Weg ins Ausland ebnet. Betrachten Sie die 672.000 Reichsmark als... Ticket in die Freiheit. Unterschreiben Sie hier.</p><hr><h2 id="szene-5-die-„arisierung-gala-1936" tabindex="-1">Szene 5: Die „Arisierung-Gala“ 1936 <a class="header-anchor" href="#szene-5-die-„arisierung-gala-1936" aria-label="Permalink to &quot;Szene 5: Die „Arisierung-Gala“ 1936&quot;">​</a></h2><p><strong>Ort:</strong> Ein prunkvoller Festsaal. <strong>Zeit:</strong> Der Abend nach der Unterzeichnung, Mai 1936.</p><p>August Diehl brilliert in einer Szene, in der Helmut als „Retter des Duisburger Einzelhandels“ gefeiert wird. Er trägt Frack. Die Sektkorken knallen. Im Hintergrund hängt bereits der Entwurf für die erste Zeitungsanzeige.</p><p><strong>ERZÄHLER (Minichmayr, Off-Stimme)</strong> Sie feierten nicht nur einen Kauf. Sie feierten die „Marktbereinigung“. Helmut Horten stand in der Mitte und ließ die ersten Anzeigen drucken: „Ab heute in arischem Besitz“. Er wusste: Ein Vermögen, das auf dem Unrecht anderer gründet, glänzt am hellsten, wenn man es mit dem Stolz der Nation poliert.</p><p>Helmut hebt sein Glas.</p><p><strong>HELMUT</strong> Auf die Zukunft! Auf ein Deutschland, in dem jedes Schaufenster eine Geschichte von... Ordnung erzählt.</p><hr><h2 id="szene-6-das-schweigen-der-vertrage-neu" tabindex="-1">Szene 6: Das Schweigen der Verträge (NEU) <a class="header-anchor" href="#szene-6-das-schweigen-der-vertrage-neu" aria-label="Permalink to &quot;Szene 6: Das Schweigen der Verträge (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Das Archiv des Kaufhauses. <strong>Zeit:</strong> 1939.</p><p>Helmut lässt die alten Firmenunterlagen der Alsbergs vernichten. Ein riesiger Aktenvernichter (eine frühe Version der Reisswolf-Mentalität) frisst sich durch das Papier.</p><p><strong>HELMUT</strong> (beobachtet den Vorgang) Papier brennt gut. Aber es ist besser, es zu zerkleinern. Dann bleibt nichts übrig. Nicht einmal Asche, die man untersuchen könnte.</p><p>Er nimmt ein letztes Foto von Siegfried Alsberg und schiebt es in den Schlitz. August Diehls Gesicht bleibt dabei völlig emotionslos.</p><hr><h2 id="szene-7-die-„marktbereinigung-als-kunstform-neu" tabindex="-1">Szene 7: Die „Marktbereinigung“ als Kunstform (NEU) <a class="header-anchor" href="#szene-7-die-„marktbereinigung-als-kunstform-neu" aria-label="Permalink to &quot;Szene 7: Die „Marktbereinigung“ als Kunstform (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Ein modern gestaltetes Schaufenster. <strong>Zeit:</strong> 1940.</p><p>Helmut arrangiert höchstpersönlich die Puppen. Er entfernt alles, was an die „jüdische Ästhetik“ erinnern könnte. Er platziert eine Hakenkreuzfahne diskret, aber unübersehbar im Hintergrund.</p><p><strong>HELMUT</strong> Es geht um die Perspektive. Der Kunde will nicht wissen, wer hier vorher war. Er will wissen, was er heute bekommt. Ein Schnäppchen ist ein Schnäppchen. Egal, wie man es nennt.</p><p>Er tritt einen Schritt zurück und betrachtet sein Werk. Das Licht der Straßenlaternen spiegelt sich in seinen Brillengläsern.</p><hr><h2 id="szene-8-der-schatten-des-krieges-neu" tabindex="-1">Szene 8: Der Schatten des Krieges (NEU) <a class="header-anchor" href="#szene-8-der-schatten-des-krieges-neu" aria-label="Permalink to &quot;Szene 8: Der Schatten des Krieges (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Ein Bunker während eines Luftangriffs. <strong>Zeit:</strong> 1943.</p><p>Helmut sitzt ruhig da, während die Erde bebt. Er studiert Bilanzen bei Kerzenlicht.</p><p><strong>HELMUT</strong> Wenn alles zerstört ist, wird der Bedarf am größten sein. Wer die Waren hat, wird der König der Ruinen sein. Ich muss nur warten. Die Zeit arbeitet für mich.</p><p>Er löscht die Kerze mit den Fingern aus. Der Schmerz scheint ihn nicht zu berühren.</p><p><strong>FADE OUT.</strong></p>',56)])])}const m=r(s,[["render",a]]);export{c as __pageData,m as default};
